#!/usr/bin/env node
// SYNTHETIC FIXTURE BUILDER. Regenerates history.synthetic.bundle.mjs from
// synthetic-bundle.txt. The output has the exact shape tools/export-bundle.mjs
// writes, but its provenance fields say "synthetic" and it is NOT an export of
// the Epinoic History knowledge base. test/fixtures.test.js checks that the
// committed module matches this builder's output.
//
//   node fixtures/synthetic/build-synthetic-bundle.mjs           (write)
//   node fixtures/synthetic/build-synthetic-bundle.mjs --check   (verify only)

import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
export const SYNTHETIC_TEXT_PATH = join(here, "synthetic-bundle.txt");
export const SYNTHETIC_MODULE_PATH = join(here, "history.synthetic.bundle.mjs");

export const SYNTHETIC_PROVENANCE = Object.freeze({
  slug: "history",
  sourceRepo: "synthetic/offline-fixture",
  sourceCommit: "synthetic-no-commit",
  bundlePath: "fixtures/synthetic/synthetic-bundle.txt",
  kbVersion: "synthetic-kb-0",
});

/**
 * Render a bundle module source for the given bytes and provenance.
 * @param {Uint8Array} bytes
 * @param {typeof SYNTHETIC_PROVENANCE} provenance
 */
export function renderBundleModule(bytes, provenance, header) {
  const sha256 = createHash("sha256").update(bytes).digest("hex");
  const fields = {
    schema: "epinoic.specialist-bundle-module.v1",
    slug: provenance.slug,
    sourceRepo: provenance.sourceRepo,
    sourceCommit: provenance.sourceCommit,
    bundlePath: provenance.bundlePath,
    kbVersion: provenance.kbVersion,
    sha256,
    byteLength: bytes.length,
    base64: Buffer.from(bytes).toString("base64"),
  };
  const body = Object.entries(fields)
    .map(([k, v]) => `  ${k}: ${JSON.stringify(v)}`)
    .join(",\n");
  return `${header}export const BUNDLE = Object.freeze({\n${body}\n});\n`;
}

const HEADER =
  "// SYNTHETIC TEST FIXTURE. Generated by fixtures/synthetic/build-synthetic-bundle.mjs\n" +
  "// from synthetic-bundle.txt. NOT the Epinoic History knowledge base. Do not edit.\n";

export function buildSyntheticModuleSource() {
  return renderBundleModule(readFileSync(SYNTHETIC_TEXT_PATH), SYNTHETIC_PROVENANCE, HEADER);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const source = buildSyntheticModuleSource();
  if (process.argv.includes("--check")) {
    const current = readFileSync(SYNTHETIC_MODULE_PATH, "utf8");
    if (current !== source) {
      process.stderr.write("history.synthetic.bundle.mjs is out of date; re-run the builder\n");
      process.exit(1);
    }
    process.stdout.write("history.synthetic.bundle.mjs is up to date\n");
  } else {
    writeFileSync(SYNTHETIC_MODULE_PATH, source);
    process.stdout.write(`wrote ${SYNTHETIC_MODULE_PATH}\n`);
  }
}
